<?php if ($job['has_milestones'] ?? false): ?> <a class="gh-button gh-button-secondary" href="?route=/client/jobs/milestones&amp;job_id=<?= (int)$job['id'] ?>">View Milestones</a><?php endif; ?>
</span></div>
<?php if (in_array($job['status'], ['draft','open'], true) && ($job['awarded_bid_id'] ?? null) === null && ($job['awarded_at'] ?? null) === null): ?>
<div class="gh-profile-actions gh-detail-actions jobs-management">
<?php if (!($job['has_bids'] ?? false)): ?><a class="gh-button gh-detail-icon gh-detail-edit" title="Edit job" aria-label="Edit <?= $escape($job['title']) ?>" href="?route=/client/jobs/edit&amp;id=<?= (int)$job['id'] ?>"><svg width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L21 6l-3-3L5 16z"/></svg></a><?php endif; ?>
<details data-job-delete-fallback><summary class="gh-button gh-detail-icon gh-detail-delete" title="Delete job" aria-label="Delete <?= $escape($job['title']) ?>"><svg width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M6 6l1 14h10l1-14M10 10v6m4-6v6"/></svg></summary>
<div data-job-confirm><h2>Remove job?</h2><form method="post" action="?route=/client/jobs/delete">
<input type="hidden" name="csrf_token" value="<?= $escape($token) ?>">
<input type="hidden" name="id" value="<?= (int)$job['id'] ?>">
<p><?= ($job['has_bids'] ?? false) ? 'Close this job and keep its bid history?' : 'Permanently delete this job?' ?></p>
<div class="jobs-confirm-actions"><button class="gh-button gh-button-secondary" type="button" data-job-cancel autofocus hidden>Cancel</button><button class="gh-button jobs-confirm-delete" type="submit">Confirm Delete</button></div>
</form></div></details></div>
<?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
